from __future__ import annotations

from minidb.types import (
    COMPARISON_OPS,
    And,
    ColumnDef,
    ColumnRef,
    ColumnType,
    Comparison,
    CreateTableStmt,
    DeleteStmt,
    DropTableStmt,
    Expr,
    InsertStmt,
    IsNull,
    Literal,
    Not,
    Or,
    SelectStmt,
    SQLSyntaxError,
    Statement,
    Token,
    TokenType,
    Value,
)

__all__ = ["parse", "parse_script", "parse_expression"]


def _consume_token(tokens: list[Token], expected_type: TokenType, expected_value: str = None) -> Token:
    if not tokens:
        raise SQLSyntaxError("Unexpected end of tokens")
    token = tokens.pop(0)
    if token.type != expected_type:
        raise SQLSyntaxError(f"Expected token type {expected_type}, got {token.type}")
    if expected_value is not None and token.value != expected_value:
        raise SQLSyntaxError(f"Expected token value {expected_value}, got {token.value}")
    return token

def _parse_column_def(tokens: list[Token]) -> ColumnDef:
    name = _consume_token(tokens, TokenType.IDENTIFIER).value
    _consume_token(tokens, TokenType.OPERATOR, ",")
    column_type = _consume_token(tokens, TokenType.KEYWORD).value
    if column_type == "INTEGER":
        return ColumnDef(name, ColumnType.INTEGER)
    elif column_type == "TEXT":
        return ColumnDef(name, ColumnType.TEXT)
    elif column_type == "BOOLEAN":
        return ColumnDef(name, ColumnType.BOOLEAN)
    else:
        raise SQLSyntaxError(f"Unknown column type: {column_type}")

def _parse_column_defs(tokens: list[Token]) -> tuple[ColumnDef, ...]:
    column_defs = []
    while tokens[0].type != TokenType.OPERATOR or tokens[0].value != ")":
        column_defs.append(_parse_column_def(tokens))
        if tokens[0].type == TokenType.OPERATOR and tokens[0].value == ",":
            _consume_token(tokens, TokenType.OPERATOR, ",")
    _consume_token(tokens, TokenType.OPERATOR, ")")
    return tuple(column_defs)

def _parse_create_table_stmt(tokens: list[Token]) -> CreateTableStmt:
    _consume_token(tokens, TokenType.KEYWORD, "CREATE")
    _consume_token(tokens, TokenType.KEYWORD, "TABLE")
    table_name = _consume_token(tokens, TokenType.IDENTIFIER).value
    _consume_token(tokens, TokenType.OPERATOR, "(")
    columns = _parse_column_defs(tokens)
    return CreateTableStmt(table_name, columns)

def _parse_drop_table_stmt(tokens: list[Token]) -> DropTableStmt:
    _consume_token(tokens, TokenType.KEYWORD, "DROP")
    _consume_token(tokens, TokenType.KEYWORD, "TABLE")
    table_name = _consume_token(tokens, TokenType.IDENTIFIER).value
    return DropTableStmt(table_name)

def _parse_insert_values(tokens: list[Token]) -> tuple[Value, ...]:
    _consume_token(tokens, TokenType.OPERATOR, "(")
    values = []
    while tokens[0].type != TokenType.OPERATOR or tokens[0].value != ")":
        if tokens[0].type == TokenType.INTEGER:
            values.append(int(_consume_token(tokens, TokenType.INTEGER).value))
        elif tokens[0].type == TokenType.STRING:
            values.append(_consume_token(tokens, TokenType.STRING).value)
        elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "TRUE":
            _consume_token(tokens, TokenType.KEYWORD, "TRUE")
            values.append(True)
        elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "FALSE":
            _consume_token(tokens, TokenType.KEYWORD, "FALSE")
            values.append(False)
        elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "NULL":
            _consume_token(tokens, TokenType.KEYWORD, "NULL")
            values.append(None)
        else:
            raise SQLSyntaxError(f"Invalid value type: {tokens[0].type}")
        if tokens[0].type == TokenType.OPERATOR and tokens[0].value == ",":
            _consume_token(tokens, TokenType.OPERATOR, ",")
    _consume_token(tokens, TokenType.OPERATOR, ")")
    return tuple(values)

def _parse_insert_stmt(tokens: list[Token]) -> InsertStmt:
    _consume_token(tokens, TokenType.KEYWORD, "INSERT")
    _consume_token(tokens, TokenType.KEYWORD, "INTO")
    table_name = _consume_token(tokens, TokenType.IDENTIFIER).value
    columns = None
    if tokens[0].type == TokenType.OPERATOR and tokens[0].value == "(":
        _consume_token(tokens, TokenType.OPERATOR, "(")
        columns = []
        while tokens[0].type != TokenType.OPERATOR or tokens[0].value != ")":
            columns.append(_consume_token(tokens, TokenType.IDENTIFIER).value)
            if tokens[0].type == TokenType.OPERATOR and tokens[0].value == ",":
                _consume_token(tokens, TokenType.OPERATOR, ",")
        _consume_token(tokens, TokenType.OPERATOR, ")")
    _consume_token(tokens, TokenType.KEYWORD, "VALUES")
    values = _parse_insert_values(tokens)
    return InsertStmt(table_name, tuple(columns) if columns else None, values)

def _parse_select_columns(tokens: list[Token]) -> tuple[str, ...]:
    columns = []
    while tokens[0].type != TokenType.KEYWORD or tokens[0].value != "FROM":
        if tokens[0].type == TokenType.OPERATOR and tokens[0].value == ",":
            _consume_token(tokens, TokenType.OPERATOR, ",")
        else:
            columns.append(_consume_token(tokens, TokenType.IDENTIFIER).value)
    return tuple(columns)

def _parse_select_stmt(tokens: list[Token]) -> SelectStmt:
    _consume_token(tokens, TokenType.KEYWORD, "SELECT")
    columns = None
    if tokens[0].type == TokenType.OPERATOR and tokens[0].value == "*":
        _consume_token(tokens, TokenType.OPERATOR, "*")
    else:
        columns = _parse_select_columns(tokens)
    _consume_token(tokens, TokenType.KEYWORD, "FROM")
    table_name = _consume_token(tokens, TokenType.IDENTIFIER).value
    where_expr = None
    if tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "WHERE":
        _consume_token(tokens, TokenType.KEYWORD, "WHERE")
        where_expr = parse_expression(tokens)
    return SelectStmt(table_name, columns, where_expr)

def _parse_delete_stmt(tokens: list[Token]) -> DeleteStmt:
    _consume_token(tokens, TokenType.KEYWORD, "DELETE")
    _consume_token(tokens, TokenType.KEYWORD, "FROM")
    table_name = _consume_token(tokens, TokenType.IDENTIFIER).value
    where_expr = None
    if tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "WHERE":
        _consume_token(tokens, TokenType.KEYWORD, "WHERE")
        where_expr = parse_expression(tokens)
    return DeleteStmt(table_name, where_expr)

def parse(tokens: list[Token]) -> Statement:
    if not tokens:
        raise SQLSyntaxError("No tokens provided")
    first_token = tokens[0]
    if first_token.type == TokenType.KEYWORD:
        if first_token.value == "CREATE":
            stmt = _parse_create_table_stmt(tokens)
        elif first_token.value == "DROP":
            stmt = _parse_drop_table_stmt(tokens)
        elif first_token.value == "INSERT":
            stmt = _parse_insert_stmt(tokens)
        elif first_token.value == "SELECT":
            stmt = _parse_select_stmt(tokens)
        elif first_token.value == "DELETE":
            stmt = _parse_delete_stmt(tokens)
        else:
            raise SQLSyntaxError(f"Unknown keyword: {first_token.value}")
    else:
        raise SQLSyntaxError(f"Unexpected token type: {first_token.type}")
    if tokens:
        if tokens[0].type == TokenType.OPERATOR and tokens[0].value == ";":
            _consume_token(tokens, TokenType.OPERATOR, ";")
        if tokens[0].type != TokenType.EOF:
            raise SQLSyntaxError("Trailing tokens after statement")
    return stmt

def parse_script(tokens: list[Token]) -> list[Statement]:
    statements = []
    while tokens[0].type != TokenType.EOF:
        if tokens[0].type == TokenType.OPERATOR and tokens[0].value == ";":
            _consume_token(tokens, TokenType.OPERATOR, ";")
            continue
        stmt = parse(tokens)
        statements.append(stmt)
        if tokens[0].type == TokenType.OPERATOR and tokens[0].value == ";":
            _consume_token(tokens, TokenType.OPERATOR, ";")
    return statements

def parse_expression(tokens: list[Token]) -> Expr:
    return _parse_or_expr(tokens)

def _parse_or_expr(tokens: list[Token]) -> Expr:
    left = _parse_and_expr(tokens)
    while tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "OR":
        _consume_token(tokens, TokenType.KEYWORD, "OR")
        right = _parse_and_expr(tokens)
        left = Or(left, right)
    return left

def _parse_and_expr(tokens: list[Token]) -> Expr:
    left = _parse_not_expr(tokens)
    while tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "AND":
        _consume_token(tokens, TokenType.KEYWORD, "AND")
        right = _parse_not_expr(tokens)
        left = And(left, right)
    return left

def _parse_not_expr(tokens: list[Token]) -> Expr:
    if tokens[0].type == TokenType.KEYWORD and tokens[0].value == "NOT":
        _consume_token(tokens, TokenType.KEYWORD, "NOT")
        operand = _parse_not_expr(tokens)
        return Not(operand)
    return _parse_predicate(tokens)

def _parse_predicate(tokens: list[Token]) -> Expr:
    left = _parse_primary(tokens)
    if tokens and tokens[0].type == TokenType.OPERATOR and tokens[0].value in COMPARISON_OPS:
        op = _consume_token(tokens, TokenType.OPERATOR).value
        right = _parse_primary(tokens)
        return Comparison(op, left, right)
    elif tokens and tokens[0].type == TokenType.KEYWORD and tokens[0].value == "IS":
        _consume_token(tokens, TokenType.KEYWORD, "IS")
        negated = False
        if tokens[0].type == TokenType.KEYWORD and tokens[0].value == "NOT":
            _consume_token(tokens, TokenType.KEYWORD, "NOT")
            negated = True
        _consume_token(tokens, TokenType.KEYWORD, "NULL")
        return IsNull(left, negated)
    else:
        raise SQLSyntaxError("Invalid predicate")

def _parse_primary(tokens: list[Token]) -> Expr:
    if tokens[0].type == TokenType.INTEGER:
        value = int(_consume_token(tokens, TokenType.INTEGER).value)
        return Literal(value)
    elif tokens[0].type == TokenType.STRING:
        value = _consume_token(tokens, TokenType.STRING).value
        return Literal(value)
    elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "TRUE":
        _consume_token(tokens, TokenType.KEYWORD, "TRUE")
        return Literal(True)
    elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "FALSE":
        _consume_token(tokens, TokenType.KEYWORD, "FALSE")
        return Literal(False)
    elif tokens[0].type == TokenType.KEYWORD and tokens[0].value == "NULL":
        _consume_token(tokens, TokenType.KEYWORD, "NULL")
        return Literal(None)
    elif tokens[0].type == TokenType.IDENTIFIER:
        name = _consume_token(tokens, TokenType.IDENTIFIER).value
        return ColumnRef(name)
    elif tokens[0].type == TokenType.OPERATOR and tokens[0].value == "(":
        _consume_token(tokens, TokenType.OPERATOR, "(")
        expr = parse_expression(tokens)
        _consume_token(tokens, TokenType.OPERATOR, ")")
        return expr
    else:
        raise SQLSyntaxError("Invalid primary expression")

